    public Object parsePosition(Object position, Object... optionalArgs)
    {
        //
        //     {
        //         "id": "0x49ddd7a564c978f6e4089ff8355b56a42b7e2d48ba282cb5aad60f04bea0ec3-BTC-USD-PERP",
        //         "market": "BTC-USD-PERP",
        //         "status": "OPEN",
        //         "side": "LONG",
        //         "size": "0.01",
        //         "average_entry_price": "64839.96053748",
        //         "average_entry_price_usd": "64852.9",
        //         "realized_pnl": "0",
        //         "unrealized_pnl": "-2.39677214",
        //         "unrealized_funding_pnl": "-0.11214013",
        //         "cost": "648.39960537",
        //         "cost_usd": "648.529",
        //         "cached_funding_index": "35202.1002351",
        //         "last_updated_at": 1718950074249,
        //         "last_fill_id": "1718947571560201703986670001",
        //         "seq_no": 1718950074249176253,
        //         "liquidation_price": ""
        //     }
        //
        Object market = Helpers.getArg(optionalArgs, 0, null);
        Object marketId = this.safeString(position, "market");
        market = this.safeMarket(marketId, market);
        Object symbol = Helpers.GetValue(market, "symbol");
        Object side = this.safeStringLower(position, "side");
        Object quantity = this.safeString(position, "size");
        if (Helpers.isTrue(!Helpers.isEqual(side, "long")))
        {
            quantity = Precise.stringMul("-1", quantity);
        }
        Object timestamp = this.safeInteger(position, "time");
        final Object finalSide = side;
        final Object finalQuantity = quantity;
        return this.safePosition(new java.util.HashMap<String, Object>() {{
            put( "info", position );
            put( "id", Paradex.this.safeString(position, "id") );
            put( "symbol", symbol );
            put( "entryPrice", Paradex.this.safeString(position, "average_entry_price") );
            put( "markPrice", null );
            put( "notional", null );
            put( "collateral", Paradex.this.safeString(position, "cost") );
            put( "unrealizedPnl", Paradex.this.safeString(position, "unrealized_pnl") );
            put( "side", finalSide );
            put( "contracts", Paradex.this.parseNumber(finalQuantity) );
            put( "contractSize", null );
            put( "timestamp", timestamp );
            put( "datetime", Paradex.this.iso8601(timestamp) );
            put( "hedged", null );
            put( "maintenanceMargin", null );
            put( "maintenanceMarginPercentage", null );
            put( "initialMargin", null );
            put( "initialMarginPercentage", null );
            put( "leverage", null );
            put( "liquidationPrice", null );
            put( "marginRatio", null );
            put( "marginMode", null );
            put( "percentage", null );
        }});
    }

